const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m])),usd=v=>Number(v)>0?new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD',minimumFractionDigits:2}).format(Number(v)):'Por definir',ha=v=>(v!==''&&v!=null&&Number.isFinite(Number(v)))?new Intl.NumberFormat('es-EC',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v))+' ha':'Pendiente de validación';
const css='body{font-family:Arial,sans-serif;color:#20323b;line-height:1.45;margin:40px}h1{color:#0e536b}h2{color:#164d5e;border-bottom:1px solid #ccd8dd;padding-bottom:5px;margin-top:24px}table{border-collapse:collapse;width:100%;margin:10px 0 18px}th,td{border:1px solid #d4dee2;padding:8px;text-align:left}th{background:#edf5f7}.note{background:#fff8e8;border:1px solid #efd28f;padding:10px;margin:12px 0}.tag{display:inline-block;background:#eaf4f7;padding:4px 8px;border-radius:14px;font-size:11px;margin-right:5px}.footer{margin-top:35px;padding-top:10px;border-top:1px solid #ccd8dd;color:#60727b;font-size:11px}@media print{body{margin:20mm}.no-print{display:none}}';
const table=a=>'<table>'+a.map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td></tr>`).join('')+'</table>',list=a=>'<ul>'+a.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>';
function terr(p){const r=window.SmartRiskTerritorialDefaults,m=window.SmartRiskEcuadorMarket,d=r?.draft,k=`${p.province}|${p.canton}`,x=r?.official?.[k]||m?.records?.find(q=>q.province===p.province&&q.canton===p.canton)||{},ok=d&&d.province===p.province&&d.canton===p.canton;return{ou:x.urbanOfficialHa??'',oe:x.expansionOfficialHa??'',pu:p.projectUrbanHa??(ok?d.projectUrbanHa:''),pe:p.projectExpansionHa??(ok?d.projectExpansionHa:''),instrument:x.instrument||'',source:[x.sourceDate,x.sourceLabel].filter(Boolean).join(' · ')}}
function econ(p){if(window.SmartRiskSercopCase?.project?.id===p.id&&window.SmartRiskSercopFlow)return window.SmartRiskSercopFlow.finance(window.SmartRiskSercopFlow.index);const g=Number(String(p.gate||'G0').replace('G',''))||0,v=Number(p.price)||0,c=Number(p.cost)||0;return{reference:Number(p.referenceBudget)||0,target:g===3?v:0,offer:g>=4&&g<5?v:0,contract:g>=5?v:0,bac:c,committed:Number(p.committed)||0,actual:Number(p.actual)||0,eac:c,invoiced:Number(p.invoiced)||0,collected:Number(p.collected)||0}}
function method(s){s=String(s||'').toLowerCase();if(s.includes('microzon'))return['Revisión de PDOT/PUGS, cartografía y estudios previos.','Definición del área de estudio y diseño de campaña.','Investigación geotécnica: perforaciones, SPT, muestreo y ensayos según alcance.','Investigación geofísica mediante técnicas Vs y/o HVSR según objetivos.','Integración SIG, modelación y delimitación de unidades o microzonas.','Análisis de respuesta del sitio y productos definidos por TDR.','QA/QC, control de versiones, cartografía, bases y entrega.'];return['Revisión de antecedentes y definición del alcance.','Investigación de campo y procesamiento según TDR.','Muestreo/laboratorio y/o procesamiento instrumental cuando corresponda.','Integración e interpretación técnica con soporte SIG.','QA/QC y entrega de informe, anexos, resultados y bases.']}
function html(type){const p=project(),t=terr(p),e=econ(p),internal=type==='internal',amount=e.offer||e.contract||e.target||Number(p.price)||0,den=e.contract||e.offer||e.target||Number(p.price)||0,mg=den&&e.eac?((den-e.eac)/den*100):null,area=(Number(t.pu)||0)+(Number(t.pe)||0),title=internal?'INFORME TÉCNICO-ECONÓMICO':'PROPUESTA TÉCNICO-ECONÓMICA',external=[['Valor de la propuesta / referencia vigente',`<strong>${usd(amount)}</strong>`],['Impuestos','Según régimen aplicable y condiciones del proceso.'],['Forma de pago','Según TDR, contrato o negociación aprobada.'],['Vigencia','Por definir en la versión formal.']],inside=[['Presupuesto referencial',usd(e.reference)],['Precio objetivo',usd(e.target)],['Oferta económica',usd(e.offer)],['Valor contractual',usd(e.contract)],['BAC / costo previsto',usd(e.bac)],['Comprometido',usd(e.committed)],['Costo real',usd(e.actual)],['EAC',usd(e.eac)],['Facturado',usd(e.invoiced)],['Cobrado',usd(e.collected)],['Margen previsto',mg==null?'Por definir':mg.toFixed(1)+'%']];let detail='';if(internal&&p.id==='salinas')detail='<h3>Desglose interno registrado</h3>'+table([['Componente geotécnico',usd(73190)],['Componente geofísico',usd(37000)],['Personal y administración contractual',usd(34000)],['Especialidades / integración técnica',usd(70653)],['Subtotal técnico',usd(214843)],['Indirectos + contingencia',usd(33301)],['Margen',usd(37222)],['Precio base',usd(285366)]])+'<div class="note">Estructura referencial interna actualmente registrada para Salinas.</div>';const sercop=window.SmartRiskSercopCase?.project?.id===p.id?'<div class="note"><b>Trazabilidad SERCOP:</b> datos públicos de proceso/contrato se mantienen separados de costos y ejecución simulados internos.</div>':'';const risks=internal?'<h2>7. Riesgos y control</h2>'+(p.alerts?.length?list(p.alerts):'<p>Sin alertas registradas.</p>')+`<p><b>Gate actual:</b> ${esc(p.gate)} · ${esc(p.stage)}.</p>`:'';return`<!doctype html><html><head><meta charset="utf-8"><title>${title}</title><style>${css}</style></head><body><h1>${title}</h1><p>SmartRisk Consultoría · ${new Date().toLocaleDateString('es-EC')}</p><p><span class="tag">${esc(p.code)}</span><span class="tag">${esc(p.gate)}</span><span class="tag">${esc(p.stage)}</span></p><h2>1. Identificación</h2>${table([['Entidad / territorio',`${esc(p.canton)}, ${esc(p.province)}`],['Servicio',esc(p.service)],['Código',esc(p.code)],['Etapa / Gate',`${esc(p.stage)} · ${esc(p.gate)}`]])}<h2>2. Base territorial</h2>${table([['Área urbana oficial PDOT/PUGS',ha(t.ou)],['Expansión oficial PDOT/PUGS',ha(t.oe)],['Área utilizada para el proyecto',ha(area||'')],['Instrumento / fuente',esc(t.instrument||'Pendiente de validación')],['Referencia',esc(t.source||'Pendiente')]])}<h2>3. Objeto</h2><p>Desarrollar ${esc(String(p.service||'servicio técnico').toLowerCase())} para el territorio indicado, con trazabilidad documental y productos verificables conforme al TDR, alcance contratado o versión aprobada.</p><h2>4. Alcance y metodología</h2>${list(method(p.service))}<h2>5. Entregables</h2>${list(['Plan de trabajo y metodología.','Evidencias de campo/procesamiento según alcance.','Resultados técnicos, anexos y controles QA/QC.','Cartografía y/o bases geográficas cuando corresponda.','Informe técnico y expediente de entrega.'])}<h2>6. Componente económico</h2>${table(internal?inside:external)}${detail}${sercop}${risks}<h2>${internal?'8':'7'}. Supuestos y condiciones</h2>${list(['Cantidades definitivas de puntos, metros, ensayos y productos se ajustan al TDR, polígono real y condiciones de campo.','La referencia PDOT/PUGS se conserva y cualquier ajuste de área queda trazado.','Permisos de acceso y restricciones operativas pueden afectar plazo y costos.','Impuestos y condiciones de pago solo se incorporan cuando estén definidos.'])}<h2>${internal?'9':'8'}. Cierre</h2><p>${internal?'Este informe consolida la información técnica y económica disponible para apoyar decisión gerencial, control del Gate y rentabilidad.':'Esta propuesta es una base técnico-económica. Antes de emisión formal deben confirmarse alcance, cantidades, cronograma, impuestos, forma de pago, firmas y versión final.'}</p><div class="footer">Generado desde SmartRisk Consultoría. Sujeto a revisión y control de versión antes de uso contractual.</div></body></html>`}
function dl(type){const p=project(),a=document.createElement('a'),b=new Blob(['\ufeff',html(type)],{type:'application/msword;charset=utf-8'});a.href=URL.createObjectURL(b);a.download=`${type==='internal'?'Informe_TE':'Propuesta_TE'}_${String(p.code||p.canton).replace(/[^a-z0-9_-]+/gi,'_')}.doc`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
