function modal(){let m=document.getElementById('srExportModal');if(m)return m;m=document.createElement('div');m.id='srExportModal';m.className='modal';m.innerHTML='<div class="back" data-x></div><section class="modal-card"><div class="modal-head"><div><strong>Informe / Propuesta técnico-económica</strong><div class="muted">Datos vigentes del proyecto seleccionado.</div></div><button class="btn" data-x>✕</button></div><div class="modal-body"><div class="detail"><div class="box"><h3>Propuesta para cliente</h3><p class="muted">No muestra costos internos ni margen.</p><button class="btn primary" data-d="client">Descargar Word (.doc)</button> <button class="btn" data-p="client">Vista PDF / imprimir</button></div><div class="box"><h3>Informe interno</h3><p class="muted">Incluye BAC, costos, EAC, margen y alertas.</p><button class="btn primary" data-d="internal">Descargar Word (.doc)</button> <button class="btn" data-p="internal">Vista PDF / imprimir</button></div></div><div class="callout warn" style="margin-top:10px"><strong>Control de emisión.</strong><div class="muted">Revisar TDR, cantidades, impuestos, forma de pago, firmas y versión final antes de uso contractual.</div></div></div><div class="modal-foot"><button class="btn" data-x>Cerrar</button></div></section>';document.body.appendChild(m);m.querySelectorAll('[data-x]').forEach(b=>b.onclick=()=>m.classList.remove('open'));m.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>dl(b.dataset.d));m.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>print(b.dataset.p));return m}
function inject(){if(['negocios','mapa'].includes(s.section))return;const h=document.querySelector('#main .panel-head .panel-actions');if(!h||h.querySelector('[data-te]'))return;const b=document.createElement('button');b.className='btn';b.dataset.te='1';b.textContent='↓ Informe / Propuesta';b.onclick=()=>modal().classList.add('open');h.prepend(b)}
new MutationObserver(()=>setTimeout(inject,0)).observe(document.getElementById('main'),{childList:true,subtree:true});setTimeout(inject,500);window.SmartRiskProposalExport={html,download:dl,print,economics:econ,territory:terr};
